// --- Dijkstra: minimise the SUM of weights. Non-negative only. ---
vector<long> dijkstra(vector<vector<pair<int,int>>>& adj, int src, int n) {
    vector<long> dist(n, LONG_MAX);
    dist[src] = 0;
    priority_queue<pair<long,int>, vector<pair<long,int>>,
                   greater<>> pq;       // min-heap of (distance, node)
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, node] = pq.top(); pq.pop();
        if (d > dist[node]) continue;   // lazy deletion: stale duplicate
        for (auto [nxt, w] : adj[node]) {
            long nd = d + w;            // bottleneck variant: max(d, w)
            if (nd < dist[nxt]) { dist[nxt] = nd; pq.push({nd, nxt}); }
        }
    }
    return dist;
}

// --- Prim's MST ---
long prim(int n) {
    vector<bool> visited(n, false);
    priority_queue<pair<long,int>, vector<pair<long,int>>, greater<>> pq;
    pq.push({0, 0});
    long total = 0; int count = 0;
    while (count < n) {
        auto [cost, node] = pq.top(); pq.pop();
        if (visited[node]) continue;    // attached already, by a cheaper edge
        visited[node] = true; total += cost; count++;
        for (int nxt = 0; nxt < n; nxt++)
            if (!visited[nxt]) pq.push({weight(node, nxt), nxt});
    }
    return total;
}

// --- Bellman-Ford with a cap on edges used ---
vector<long> bellmanFord(int n, vector<vector<int>>& edges, int src, int rounds) {
    vector<long> dist(n, LONG_MAX);
    dist[src] = 0;
    for (int i = 0; i < rounds; i++) {
        vector<long> snapshot = dist;   // CRITICAL: relax against the
        for (auto& e : edges) {         // previous round only
            if (snapshot[e[0]] == LONG_MAX) continue;
            dist[e[1]] = min(dist[e[1]], snapshot[e[0]] + e[2]);
        }
    }
    return dist;
}

