// JavaScript has no built-in heap — assume a MinHeap keyed on the first
// tuple element, or hand-roll one (see the Heap category's template).

// --- Dijkstra: minimise the SUM of weights. Non-negative only. ---
const dijkstra = (adj, src, n) => {
  const dist = new Array(n).fill(Infinity);
  dist[src] = 0;
  const pq = new MinHeap((x) => x[0]);     // [distance, node]
  pq.push([0, src]);
  while (pq.size()) {
    const [d, node] = pq.pop();
    if (d > dist[node]) continue;          // lazy deletion: stale duplicate
    for (const [nxt, w] of adj[node]) {
      const nd = d + w;                    // bottleneck: Math.max(d, w)
      if (nd < dist[nxt]) { dist[nxt] = nd; pq.push([nd, nxt]); }
    }
  }
  return dist;
};

// --- Prim's MST ---
const prim = (n, weight) => {
  const visited = new Set();
  const pq = new MinHeap((x) => x[0]);     // [cost to attach, node]
  pq.push([0, 0]);
  let total = 0;
  while (visited.size < n) {
    const [cost, node] = pq.pop();
    if (visited.has(node)) continue;       // attached already
    visited.add(node);
    total += cost;
    for (let nxt = 0; nxt < n; nxt++)
      if (!visited.has(nxt)) pq.push([weight(node, nxt), nxt]);
  }
  return total;
};

// --- Bellman-Ford with a cap on edges used ---
const bellmanFord = (n, edges, src, rounds) => {
  let dist = new Array(n).fill(Infinity);
  dist[src] = 0;
  for (let i = 0; i < rounds; i++) {
    const snapshot = [...dist];            // CRITICAL: previous round only
    for (const [u, v, w] of edges) {
      if (snapshot[u] === Infinity) continue;
      dist[v] = Math.min(dist[v], snapshot[u] + w);
    }
  }
  return dist;
};

