            visited[u] = true;
            cost += minDist[u]; connected++;
            for (int v = 0; v < n; v++) {
                int d = abs(points[u][0]-points[v][0]) + abs(points[u][1]-points[v][1]);
                minDist[v] = min(minDist[v], d);
            }
        }
        return cost;
    }
};

