        const [d, u] = pq.shift();
        if (d > dist[u]) continue;
        for (const [v, w] of graph[u])
            if (dist[u] + w < dist[v]) { dist[v] = dist[u] + w; pq.push([dist[v], v]); }
    }
    const result = Math.max(...dist.slice(1));
    return result === Infinity ? -1 : result;
