def alienOrder(words):
    adj = {c: set() for w in words for c in w}
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i+1]
        min_len = min(len(w1), len(w2))
        if w1[:min_len] == w2[:min_len] and len(w1) > len(w2):
            return ""  # invalid
        for j in range(min_len):
            if w1[j] != w2[j]:
                adj[w1[j]].add(w2[j])
                break
    visited = {}  # False=in-progress, True=done
    result = []
    def dfs(c):
        if c in visited:
            return visited[c]  # True=ok, False=cycle
        visited[c] = False
        for nei in adj[c]:
            if not dfs(nei): return False
        visited[c] = True
        result.append(c)
        return True
    for c in adj:
        if not dfs(c): return ""
    return "".join(result[::-1])

